INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 6 > Serviceanfragen > Bearbeitung
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Müssen Serviceanfragen immer sofort bearbeitet werden, um den Betrieb aufrechtzuerhalten?', 2, '[{"text": "Nein", "correct": true, "because": "Priorisierung ist oft notwendig"}, {"text": "Ja", "correct": false, "because": "Sofortigkeit hängt von Dringlichkeit ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Serviceanfragen ohne ein Ticket-System effizient bearbeitet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Manuell möglich, aber weniger strukturiert"}, {"text": "Nein", "correct": false, "because": "Ticket-Systeme helfen, sind aber nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Bearbeitung von Serviceanfragen unabhängig von der Verfügbarkeit von Fachpersonal?', 2, '[{"text": "Nein", "correct": true, "because": "Fachkräfte sind oft erforderlich"}, {"text": "Ja", "correct": false, "because": "Personal beeinflusst Bearbeitung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Bearbeitung von Serviceanfragen automatisiert werden, ohne menschliches Eingreifen?', 2, '[{"text": "Ja", "correct": true, "because": "Automatisierung ist bei Standardanfragen möglich"}, {"text": "Nein", "correct": false, "because": "Automatisierung ist machbar, aber nicht immer vollständig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Serviceanfragen ohne dokumentierte Bearbeitungsschritte nachvollziehbar?', 2, '[{"text": "Nein", "correct": true, "because": "Dokumentation erleichtert Nachverfolgung"}, {"text": "Ja", "correct": false, "because": "Ohne Dokumentation fehlt Transparenz"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches System wird häufig zur strukturierten Bearbeitung von Serviceanfragen eingesetzt?', 3, '[{"text": "Helpdesk-Ticket-System", "correct": true, "because": "Organisiert Anfragen effizient"}, {"text": "Textverarbeitungsprogramm", "correct": false, "because": "Ungeeignet für Verwaltung"}, {"text": "Netzwerkscanner", "correct": false, "because": "Für Analyse, nicht Bearbeitung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt ist bei der Bearbeitung einer Serviceanfrage typischerweise der erste?', 2, '[{"text": "Erfassung der Anfrage", "correct": true, "because": "Grundlage für weitere Schritte"}, {"text": "Lösung des Problems", "correct": false, "because": "Erst nach Analyse"}, {"text": "Abschlussbericht", "correct": false, "because": "Letzter Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der Bearbeitung von Serviceanfragen?', 2, '[{"text": "Wiederherstellung der Funktionalität", "correct": true, "because": "Fokus auf Problemlösung"}, {"text": "Erhöhung der Systemkosten", "correct": false, "because": "Nicht gewünscht"}, {"text": "Verlängerung der Bearbeitungszeit", "correct": false, "because": "Gegenteil ist Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler kann bei der Bearbeitung von Serviceanfragen durch mangelnde Kommunikation entstehen?', 3, '[{"text": "Verzögerungen", "correct": true, "because": "Fehlende Absprache verlangsamt Prozesse"}, {"text": "Schnellere Lösung", "correct": false, "because": "Unrealistisch"}, {"text": "Automatische Eskalation", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium wird oft verwendet, um die Dringlichkeit einer Serviceanfrage zu bewerten?', 2, '[{"text": "Auswirkung auf den Betrieb", "correct": true, "because": "Bestimmt Priorität"}, {"text": "Anzahl der beteiligten Personen", "correct": false, "because": "Nur ein Faktor"}, {"text": "Zeitpunkt der Anfrage", "correct": false, "because": "Weniger entscheidend"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Schritte umfasst die Bearbeitung einer Serviceanfrage typischerweise?', 4, '[{"text": "Erfassung", "correct": true, "because": "Startpunkt"}, {"text": "Analyse", "correct": true, "because": "Problemidentifikation"}, {"text": "Lösung", "correct": true, "because": "Behebung des Problems"}, {"text": "Farbauswahl der Tickets", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools können die Bearbeitung von Serviceanfragen unterstützen?', 3, '[{"text": "Ticket-Systeme", "correct": true, "because": "Strukturierte Verwaltung"}, {"text": "Remote-Desktop-Software", "correct": true, "because": "Direkte Problemlösung"}, {"text": "Monitoring-Tools", "correct": true, "because": "Problemfrüherkennung"}, {"text": "Grafikdesign-Software", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei der Bearbeitung von Serviceanfragen auftreten?', 4, '[{"text": "Fehlende Informationen", "correct": true, "because": "Erschwert Analyse"}, {"text": "Ressourcenmangel", "correct": true, "because": "Verzögert Bearbeitung"}, {"text": "Kommunikationsprobleme", "correct": true, "because": "Führt zu Missverständnissen"}, {"text": "Schnellere Systemleistung", "correct": false, "because": "Kein Problem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Effizienz der Bearbeitung von Serviceanfragen?', 3, '[{"text": "Kompetenz des Personals", "correct": true, "because": "Wissen beschleunigt Lösung"}, {"text": "Qualität der Dokumentation", "correct": true, "because": "Klarheit hilft"}, {"text": "Verfügbarkeit von Tools", "correct": true, "because": "Unterstützt Prozesse"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine strukturierte Bearbeitung von Serviceanfragen?', 3, '[{"text": "Schnellere Problemlösung", "correct": true, "because": "Effiziente Prozesse"}, {"text": "Bessere Nachverfolgbarkeit", "correct": true, "because": "Dokumentation hilft"}, {"text": "Höhere Kundenzufriedenheit", "correct": true, "because": "Zuverlässige Bearbeitung"}, {"text": "Geringere Hardwarekosten", "correct": false, "because": "Nicht direkt relevant"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Bearbeitung von Serviceanfragen erfordert oft Teamarbeit. b) Jede Serviceanfrage muss manuell gelöst werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Teamarbeit ja, Automatisierung möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Ticket-System kann die Bearbeitungszeit verkürzen. b) Serviceanfragen sind immer hardwarebezogen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ticket-System ja, Anfragen vielfältig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Priorisierung von Serviceanfragen kann die Effizienz steigern. b) Die Bearbeitung ist unabhängig von der Problemursache.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Priorisierung ja, Ursache relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Eine gute Dokumentation erleichtert die Bearbeitung von Serviceanfragen. b) Alle Serviceanfragen haben dieselbe Dringlichkeit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Dokumentation ja, Dringlichkeit variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Bearbeitung von Serviceanfragen kann eskaliert werden, wenn nötig. b) Automatisierte Antworten sind bei jeder Anfrage ausreichend.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Eskalation ja, Automatisierung begrenzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

